export default function TitleText({ products }) {

  const Typograph = () => {
    if (products) {
      return (
        <Typography variant="h5" gutterBottom>
          {products.type.Type}
        </Typography>
      )
    }
    else {
      return (
        <div></div>
      )
    }
  }
}