// @ts-nocheck
import * as React from 'react';
import { LineChart } from '@mui/x-charts/LineChart';
import Box from '@mui/material/Box';
import { ScatterChart } from '@mui/x-charts/ScatterChart';
import dayjs from "dayjs";
import { useScatterSeries, useXScale, useYScale } from '@mui/x-charts/hooks';
import { AxisConfig } from '@mui/x-charts-pro'
import { ChartsReferenceLine } from '@mui/x-charts/ChartsReferenceLine';
import { currTheme } from '../../Theme';
import { ThemeProvider } from '@emotion/react';
import {
  blueberryTwilightPalette,
  mangoFusionPalette,
  cheerfulFiestaPalette,
  strawberrySkyPalette,
  rainbowSurgePalette,
  bluePalette,
  greenPalette,
  purplePalette,
  redPalette,
  orangePalette,
  yellowPalette,
  cyanPalette,
  pinkPalette,
} from '@mui/x-charts/colorPalettes';
function LinkPoints({ seriesId, close, width }: { seriesId: string; close?: boolean, width: number }) {
  const scatter = useScatterSeries(seriesId);
  const xScale = useXScale();
  const yScale = useYScale();
  if (!scatter) {
    return null;
  }
  const { color, data } = scatter;
  if (!data) {
    return null;
  }
  return (
    <path 
      fill="none"
      stroke={color}
      strokeWidth={width}
      d={`M ${data.map(({ x, y }) => `${xScale(x)}, ${yScale(y)}`).join(' L')}${
        close ? 'Z' : ''
      }`}
    />
  );
}

function ReformatDate(date) { 
    const result = new Date(1970,0, 1, 0, 0, 0, 0);
    result.setDate(result.getDate() + date)
    return result
}


function ReshapeProduct(product, yVal) {
   let returnArr = product.Date.map((values, index) => (
      {
          
        x: ReformatDate(values), 
        y: yVal[index], 
        id: index
      }
    ))

  return returnArr
}

export default function AverageChart({graphData}) {
  
  if (!graphData) {
    return (<div></div>)
  }
  function CreateSeries(productList) {
  let returnArr = productList.map((values, index) => (
      {  
        markerSize: 1,
        id: index, 
        data: ReshapeProduct(values, values.PercIncPerYear), 
        label: values.Name
        
      }
    ))

  let firstArr = {
    id: -1,
    data: ReshapeProduct(graphData, graphData.PercInc),
    label: 'Average Percent Increase'
  }
  let maxVal = returnArr.length 
  if (maxVal > 30) {
    maxVal = 30
  }
  return [firstArr, ...returnArr.slice(0, maxVal)]
}

  const series = CreateSeries(graphData.AllProducts)
  return (
            <ThemeProvider theme={currTheme}>
    
    <ScatterChart series={series} 
    colors={[
    'white',
    '#1b9e77',
    '#d95f02',
    '#7570b3',
    '#e7298a',
    '#66a61e',
    '#e6ab02',
    '#a6761d',
    '#666666',
    '#e41a1c',
    '#377eb8',
    '#4daf4a',
    '#984ea3',
    '#ff7f00',
    '#ffff33',
    '#a65628',
    '#f781bf',
    '#999999',
    '#e41a1c',
    '#377eb8',
  ]}
    slotProps={{
    legend: {
      direction: 'vertical',
      position: { 
        vertical: 'bottom',
      },
      sx: {
        overflowY: 'scroll',
        flexWrap: 'nowrap',
        width: '15vw',
        height: '30vh',
      },
    }
  }}
    xAxis={[
          {
            label: "Date",
            scaleType: "time",
            valueFormatter: (date) => dayjs(date).format("MM YYYY"),
          },
        ]}
    yAxis={[{ label: "Percent Increase In Price per Year", 
      valueFormatter: (value?: number) => {
              return `${value.toLocaleString()}%`

    },
    width: 60}]}
    
        >
       {series.map((item, index) => (
          <LinkPoints seriesId={index} width = {1.5}/>
      ))}
      <LinkPoints seriesId={-1} width = {5}/>
      
      <ChartsReferenceLine y={0} 
/>

    </ScatterChart>
              </ThemeProvider>
    
  );
}
