// @ts-nocheck

import * as React from 'react';
import Box from '@mui/material/Box';
import Drawer from '@mui/material/Drawer';
import CssBaseline from '@mui/material/CssBaseline';
import AppBar from '@mui/material/AppBar';
import Toolbar from '@mui/material/Toolbar';
import List from '@mui/material/List';
import Typography from '@mui/material/Typography';
import Divider from '@mui/material/Divider';
import ListItem from '@mui/material/ListItem';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemIcon from '@mui/material/ListItemIcon';
import ListItemText from '@mui/material/ListItemText';
import InboxIcon from '@mui/icons-material/MoveToInbox';
import ExpandLess from '@mui/icons-material/ExpandLess';
import NestedList from './ListItem';
import RightSide from '../RightSide/RightSide';
import Collapse from '@mui/material/Collapse';
import ExpandMore from '@mui/icons-material/ExpandMore';
import MailIcon from '@mui/icons-material/Mail';
import { useEffect, useState, useCallback } from 'react';
import { StyledList, StyledListItem } from '../MuiStyles';
import { color } from '@mui/system';
import { createTheme, ThemeProvider } from '@mui/material/styles';
import { currTheme } from '../Theme';
import TypeList from '../LeftSide/TypeList';
const drawerWidth = 240;

export default function PermanentDrawerLeft({setGrid, getSet}) {
  const [open, setOpen] = React.useState(false);
  

  const [parentCompanyData, setParentCompanyData] = useState(null);
  useEffect(() => {
            fetch('toBeUsed/ParentCompanyAverages.json')
            .then(response => response.json())
            .then(parentCompanyData => setParentCompanyData(parentCompanyData['Parent Companies']))
            .catch(error => console.error('Error fetching data:', error));
  }, []);

  const [typeAverage, setTypeAverage] = useState(null);
  useEffect(() => {
            fetch('toBeUsed/productTypeAverages.json')
            .then(response => response.json())
            .then(typeAverage => setTypeAverage(typeAverage['Parent Companies']))
            .catch(error => console.error('Error fetching data:', error));
  }, []);


  const [data, setData] = useState(null);
  useEffect(() => {
      fetch('toBeUsed/productGeneralization.json')
      .then(response => response.json())
      .then(data => setData(data))
      .catch(error => console.error('Error fetching data:', error));
  }, []);



const DropDownList =  useCallback(() => {
        return(
        <StyledList>
            {data.map((item, index) => (
                <TypeList type = {item} setGrid= {setGrid} getSet = {getSet}/>
            ))}
        </StyledList>    
    )
}, [open,data]);

  if (!data) {
    return <div>Loading...</div>;
  }
const handleClickTypeOverview = (event) => {
    setGrid({class: 0})
}

const handleClickParentCompany = (event) => {
    const pc = 'parentCompany'
    setGrid({class: 2, type: pc, list: parentCompanyData})
}

const handleClickTypeAverage = (event) => {
    const pc = 'parentCompany'
    setGrid({class: 2, type: pc, list: typeAverage})
}

const handleClick = (event) => {
    setOpen(!open);
}
  return (
    <ThemeProvider theme={currTheme}>
      <Drawer
        sx={{
          width: drawerWidth,
          flexShrink: 0,
          '& .MuiDrawer-paper': {
            backgroundColor: 'primary.main',
            width: drawerWidth,
            boxSizing: 'border-box',
          },
        }}
        variant="permanent"
        anchor="left"
      >
        
        <Divider />
        <StyledList >
            <StyledListItem key={'Overview'} disablePadding onClick={handleClickTypeOverview}>
              <ListItemButton sx={{paddingTop:'3px', paddingBottom:'3px'}}>
                <ListItemText primary={'Overview'} />
              </ListItemButton>
            </StyledListItem>
            <Divider sx={{bgcolor: 'primary.light'}}/>


            <StyledListItem key={'Parent Companies'} disablePadding onClick={handleClickParentCompany}>
              <ListItemButton sx={{paddingTop:'3px', paddingBottom:'3px'}}>
                <ListItemText primary={'Parent Companies'} />
              </ListItemButton>
            </StyledListItem>
            <Divider sx={{bgcolor: 'primary.light'}}/>


            <StyledListItem key={'Type Averages'} disablePadding onClick={handleClickTypeAverage}>
              <ListItemButton sx={{paddingTop:'3px', paddingBottom:'3px'}}>
                <ListItemText primary={'Type Averages'} />
              </ListItemButton>
            </StyledListItem>
            <Divider sx={{bgcolor: 'primary.light'}}/>


               <StyledListItem key={'All Products'} disablePadding onClick={handleClick}>
              <ListItemButton sx={{paddingTop:'3px', paddingBottom:'3px'}}>
                <ListItemIcon  sx= {{paddingLeft:'10px', color: 'secondary.light'}}>
                          {open ? <ExpandLess /> : <ExpandMore />}
                </ListItemIcon>
                <ListItemText primary={'All Products'} />
                
              </ListItemButton>
            </StyledListItem>
            <Divider sx={{bgcolor: 'primary.light'}}/>
            <Collapse in={open} timeout="auto" unmountOnExit>
            <DropDownList/>
                    </Collapse>
        </StyledList>

      </Drawer>
      </ThemeProvider>
  );
}