// @ts-nocheck


import * as React from 'react';
import Box from '@mui/material/Box';
import {
  DataGrid,
  GridColDef,
  GridColTypeDef,
  GridRenderCellParams,
  GRID_STRING_COL_DEF,
} from '@mui/x-data-grid';
import { useEffect, useState, useRef, useMemo } from 'react';
import Stack from '@mui/material/Stack';
import { ProductInterface } from '../GlobalInterfaces';
import { SparkLineChart } from '@mui/x-charts/SparkLineChart';
import { maxWidth } from '@mui/system';
import { currTheme } from '../Theme';
import {ThemeProvider }from '@mui/system';

type SparkLineChartProps = React.ComponentProps<typeof SparkLineChart>;

function GridSparklineCell(
  props: GridRenderCellParams & {
    plotType?: SparkLineChartProps['plotType'];
  },
) {
  if (props.value == null) {
    return null;
  }

  return (
    <SparkLineChart
      data={props.value}
      width={props.colDef.computedWidth}
      plotType={props.plotType}
    />
  );
}

const sparklineColumnType: GridColTypeDef<number[]> = {
  ...GRID_STRING_COL_DEF,
  type: 'custom',
  resizable: false,
  filterable: false,
  sortable: false,
  editable: false,
  groupable: false,
  display: 'flex',
  renderCell: (params) => <GridSparklineCell {...params} />,
};



const columns = [
  {
    field: 'id',
    headerName: 'Product Name',
    flex:1.5
  },

  {
    field: 'Parent Company',
    headerName: 'Parent Company',
    flex:1
  },
  {
    field: 'Length',
    headerName: 'Years Observed',
    flex:.5
  },
  {
    field: 'Price Diff',
    headerName: 'Change in Price',
    valueFormatter: (value?: number) => {
            return new Intl.NumberFormat('en-US', {
                style: 'currency',
                currency: 'USD',
                minimumFractionDigits: 2,
            }).format(value);
        },
    flex:.5
  },
    {
    field: 'PercentIncreaseYr',
    headerName: 'Average Percent Increase per Year',
    valueFormatter: (value?: number) => {
      return `${(value * 100).toLocaleString()}%`;
    },
    flex:.5
  },
  {
    field: 'Price',
    headerName: 'Price Graph',
    ...sparklineColumnType,
    flex:.6,
  },
];


export default function Grid({ update, list}) {

  const handleRowClick = (
      params, // GridRowParams
      event, // MuiEvent<React.MouseEvent<HTMLElement>>
      details, // GridCallbackDetails
    ) => {
      update({class: 1, values: params})
    }
  return (
            <ThemeProvider theme={currTheme}>
    
    <Box>
      
    <div style={{ display: 'flex', flexDirection: 'column' }}>
      
      <DataGrid
      sx={{
        boxShadow: 2,
        border: 2,
        color:'primary.contrastText',
        backgroundColor: 'primary.dark',

        "& .MuiDataGrid-row:hover": {
      backgroundColor: "#332B28"
        // color: "red"
  },
        borderColor: 'secondary.light',
      }}
      initialState={{
        pagination: {
          paginationModel: {
            pageSize: 5,
          },
        },
      }}
      rows = {list}
      columns={columns}
        repaintChangesOnly={true}
        onRowClick={handleRowClick}
      
         />
      </div>
    </Box>
                      </ThemeProvider>
    
  );
} 