import React from 'react';
import MenuAppBar from './Components/AppBar'
import { Divider } from '@mui/material';
import ChartsOverviewDemo from './Components/GraphStuff/Graph';
import { useState, useEffect, useCallback, useRef} from 'react';
import { valueReducer } from './Components/GraphStuff/GraphGrid';
import ConstantSideBar from './Components/ConstantSideBar';
import { DataToGraph } from '../../GlobalInterfaces';
import TitleText from './TitleText';
import Box from '@mui/material/Box';
import BasicLineChart from './Graphs/LineChart';
import Popup from './Components/Popup';
import Stack from '@mui/material/Stack';
import PCGrid from './PCGrid';
import Typography from '@mui/material/Typography';
import GraphGrid from './Graphs/GraphGrid';
import PopulateList from './Graphs/ParentCompanyGraph';
import PermanentDrawerLeft from './Components/LeftSide/NewDrawer';
import Grid from './Grid';
import { MenuBarProps, ParentCompanyInterface, ProductForParentCompanyInterface, ProductInterface } from './GlobalInterfaces';
import {
  DataGrid,
  GridColDef,
  GridColTypeDef,
  GridRenderCellParams,
  GRID_STRING_COL_DEF,
} from '@mui/x-data-grid';
import { height } from '@mui/system';
import { currTheme } from '../Theme';
import {ThemeProvider }from '@mui/system';




export default function RightSide({ products, currentlySelected, setCurrentlySelected }) {
  const [entireSet, setEntireSet] = useState(null);
    useEffect(() => {
          fetch('toBeUsed/EntireSet.json')
              .then(response => response.json())
              .then(entireSet => setEntireSet(new Map(entireSet.map((obj) => [obj.Product, obj.Data]))))
              .catch(error => console.error('Error fetching data:', error));
        }, []);

    


    const [currentProducts, setCurrentProducts] = useState(null);
    const [currentList, setCurrentList] = React.useState(null)
    const [primaryValueForGraph, setPrimaryValueForGraph]= React.useState(null)
    const [otherValuesForGraph, setOtherValuesForGraph] = React.useState(null)
    
    
    const getFromEntireSet=(lists)=>{
      if(entireSet) {
        if (lists) {
            let returnArr= lists.map((name) => entireSet.get(name))
            return lists.map((value, index) => 
            ({
              id: value,
              ...returnArr[index],
            }))
        }}
        return null
    }
    useEffect(() => {
        if(products){
            setCurrentList(getFromEntireSet(products.list))
        
        }
    }, [products]);

    function updateCurrentGraph(valueFromGrid) {
      if (valueFromGrid.class == 1) {
        setPrimaryValueForGraph({class: 1, values: entireSet.get(valueFromGrid.values.id)})
      } else {
      setPrimaryValueForGraph({
        class: 2,
        values: {
        id: valueFromGrid.id,
        Date: valueFromGrid.row.Dates,
        NumberOfProducts: valueFromGrid.row.Amount,
        PercInc: valueFromGrid.row.PercIncPerYear,
        Price: valueFromGrid.row.AdjustedPrice,
        AllProducts: valueFromGrid.row.Products}
      })
    }
    }

const GridCheck =  useCallback(() => {
    switch (products.class) {
      case 2:
        return (
          <PCGrid update = {updateCurrentGraph} list = {products.list}/>
        )
        break;
      case 1:
        return (
          <Grid update = {updateCurrentGraph} list = {currentList}/> 
       )
        break;
      default:
        return(
            <ThemeProvider theme={currTheme}>

          <Box sx={{height: "29vh"}}>
          <Typography variant="h4" gutterBottom color='primary.contrastText'>

            {'Are Groceries really that much more expensive Nowadays?'}
                   </Typography>

           <Typography variant="h5" gutterBottom color='primary.contrastText'>
          {"Using the internet archive, I scraped thousands of website snapshots from a popular online retailer to gather as much historical pricing data as I could find. This website represents the culmination of tens of thousands of product prices from as early as 2015"}
        </Typography>
         <Typography variant="h5" gutterBottom color='primary.contrastText'>
          {"Click any of the tabs to view pricing data. Click any row on the chart to view more complex graphs"}
        </Typography>

          </Box>
                                </ThemeProvider>
          
        )
    }
  }, [products, currentList]);


    if (!entireSet) {
          return <div>Loading...</div>;
        }


  // HEY IM HERE. YOURE ABOUT TO MAKE A GRAPH FOR PARENT COMPANY AND YOU
  // HAVE TO MAKE SURE THE CPI GRAPH CAN BE SENT OVER TO IT (YOURE COPYING PREVIOUS WORK)
  // OR YOU CAN RENDER THE CPI GRAPH IN THE PARENT COMPANY FOLDER BUT IDK IF THATS A GOOD IDEA

  
  return (
    <Box sx={{height:'95vh'}}>
        <TitleText products = {products}/>
        
        <GridCheck/>
        <GraphGrid graphData = {primaryValueForGraph} products = {products}/>
    </Box>
  );
}
